/**
 * Display sanitizers for OCR/AI-extracted vendor and product strings (CI-BUG-010).
 * Keeps ledgers readable when extraction returns address fragments, digit soup, or noise.
 */

const DIGIT_HEAVY = /(?:\d[\d\s./-]{4,}\d)/;
const ADDRESS_HINT =
  /\b(?:road|street|nagar|sector|plot|phase|pin|pincode|gstin|cin|floor|building|block|village|district|taluk|state)\b/i;
const ONLY_PUNCT = /^[\s.,;:/\\|_\-#*]+$/;
// Latin, Urdu and the Indian scripts (Devanagari through Malayalam), so regional vendor names are kept.
const HAS_LETTER = /[A-Za-z\u0600-\u06FF\u0900-\u0DFF]/;

const CONTACT_GARBAGE = /(?:@|https?:\/\/|www\.)|\.(?:mail|com|net|org|info|gmail|yahoo|outlook)\b/i;
const SHORT_FRAGMENT = /^(\S+)\s+([A-Za-z]{1,2})\.?$/;
const COMPANY_SUFFIX = /^(?:ltd|limited|pvt|private|llp|llc|inc|co|corp|company)$/i;

function isOcrGarbageLabel(value: string): boolean {
  if (CONTACT_GARBAGE.test(value)) return true;
  const match = value.match(SHORT_FRAGMENT);
  if (match && !COMPANY_SUFFIX.test(match[2])) return true;
  return false;
}

export function sanitizeDisplayVendor(
  value: unknown,
  fallback = 'Vendor unavailable'
): string {
  if (value == null) return fallback;
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    const nested = record.name ?? record.vendorName ?? record.label;
    return sanitizeDisplayVendor(nested, fallback);
  }
  const text = String(value).replace(/\s+/g, ' ').trim();
  if (!text || ONLY_PUNCT.test(text)) return fallback;
  if (text.length < 2 || text.length > 120) return fallback;
  if (!HAS_LETTER.test(text)) return fallback;
  const digitRatio = (text.match(/\d/g) || []).length / text.length;
  if (digitRatio > 0.45 || DIGIT_HEAVY.test(text)) return fallback;
  if (ADDRESS_HINT.test(text) && text.split(' ').length >= 6) return fallback;
  if (isOcrGarbageLabel(text)) return fallback;
  return text;
}

export function sanitizeDisplayProduct(
  value: unknown,
  fallback = 'Line item unavailable'
): string {
  if (value == null) return fallback;
  const text = String(value).replace(/\s+/g, ' ').trim();
  if (!text || ONLY_PUNCT.test(text)) return fallback;
  if (text.length < 2 || text.length > 160) return fallback;
  if (!HAS_LETTER.test(text) && !/\d/.test(text)) return fallback;
  const digitRatio = (text.match(/\d/g) || []).length / text.length;
  if (digitRatio > 0.7) return fallback;
  if (isOcrGarbageLabel(text)) return fallback;
  return text;
}
