import type { Document } from '../services/documentService';
import { sanitizeDisplayProduct, sanitizeDisplayVendor } from './sanitizeDisplayText';

export interface ExtractedVerificationFields {
  vendorName: string;
  date: string;
  gstin: string;
  invoiceNumber: string;
  /** Bill amount before GST; editable when OCR missed or misread it */
  amount?: string;
  /** Uncertainty answers — sent only when prompts require them */
  category?: string;
  fuelType?: string;
  electricityUnitPriceInr?: string;
  waterUnitPriceInr?: string;
  wasteUnitCostInr?: string;
  fuelUnitPriceInr?: string;
  activityQuantity?: string;
  activityUnit?: string;
  reviewConfirmed?: boolean;
}

export type UncertaintyPromptOption = {
  value: string;
  label: string;
};

export type UncertaintyPrompt = {
  id: string;
  field: string;
  prompt: string;
  inputType: 'select' | 'number' | 'confirm' | 'text' | 'bill_upload';
  options?: UncertaintyPromptOption[];
  unit?: string | null;
  required?: boolean;
  severity?: string;
  context?: Record<string, unknown>;
};

export interface BillTransactionPreviewRow {
  id: string;
  description: string;
  amount: number;
  isExcludedFromTotal?: boolean;
}

export interface ExtractedDataVerificationState {
  status: 'pending' | 'verified';
  acceptedForEmissions: boolean;
  verifiedAt?: string | null;
  correctionCount?: number;
}

const resolveItemAmount = (item: {
  total?: number;
  price?: number;
  quantity?: number;
}): number => {
  const total = Number(item.total);
  if (Number.isFinite(total) && total > 0) {
    return total;
  }
  const price = Number(item.price);
  const quantity = Number(item.quantity);
  if (Number.isFinite(price) && Number.isFinite(quantity) && price > 0 && quantity > 0) {
    return price * quantity;
  }
  return Number.isFinite(price) && price > 0 ? price : 0;
};

const formatDateForInput = (value?: string | Date | null): string => {
  if (!value) {
    return '';
  }
  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return '';
  }
  return parsed.toISOString().slice(0, 10);
};

export const readGstin = (document: Document): string => {
  const data = document.extractedData;
  if (!data) {
    return '';
  }
  return String(data.gstin || data.seller_gstin || '').trim();
};

export const readInvoiceNumber = (document: Document): string => {
  const data = document.extractedData;
  if (!data) {
    return '';
  }
  return String(data.referenceNumber || data.invoice_number || '').trim();
};

export const getBillTransactionPreview = (document: Document): BillTransactionPreviewRow[] => {
  const extractedData = document.extractedData;
  if (!extractedData) {
    return [];
  }

  let rows: BillTransactionPreviewRow[] = [];
  const items = Array.isArray(extractedData.items) ? extractedData.items : [];
  
  if (items.length > 0) {
    rows = items
      .map((item, index) => {
        const rawDescription = String(item.name || '').trim();
        const description = sanitizeDisplayProduct(rawDescription);
        if (description === 'Line item unavailable') {
          return null;
        }
        const amount = resolveItemAmount(item);
        return {
          id: `item-${index}`,
          description,
          amount,
        };
      })
      .filter((row): row is BillTransactionPreviewRow => Boolean(row));
  } else {
    const amount = Number(extractedData.amount);
    if (Number.isFinite(amount) && amount > 0) {
      rows.push({
        id: 'document-total',
        description: String(extractedData.description || 'Bill total').trim() || 'Bill total',
        amount,
      });
    }
  }

  const anyData = extractedData as any;
  const taxSplitAmt = anyData.taxSplit?.taxAmount;
  const rawGstAmount = anyData.gst_amount ?? anyData.tax_amount ?? anyData.gstAmount;
  const taxAmount = Number(taxSplitAmt ?? rawGstAmount ?? 0);
  
  if (Number.isFinite(taxAmount) && taxAmount > 0) {
    rows.push({
      id: 'gst-total',
      description: 'GST (Tax)',
      amount: taxAmount,
      isExcludedFromTotal: true
    });
  }

  return rows;
};

export const getBillTransactionTotal = (rows: BillTransactionPreviewRow[]): number =>
  rows.reduce((sum, row) => sum + (Number.isFinite(row.amount) && !row.isExcludedFromTotal ? row.amount : 0), 0);

export const formatBillAmount = (amount: number): string =>
  `₹${amount.toLocaleString('en-IN', { maximumFractionDigits: 2 })}`;

export const getUncertaintyPrompts = (document: Document): UncertaintyPrompt[] => {
  const fromMeta = document.metadata?.uncertaintyPrompts;
  if (!Array.isArray(fromMeta)) {
    return [];
  }
  return fromMeta.filter(
    (item): item is UncertaintyPrompt =>
      !!item
      && typeof item === 'object'
      && typeof (item as UncertaintyPrompt).id === 'string'
      && typeof (item as UncertaintyPrompt).field === 'string'
  );
};

export const hasOutstandingUncertainty = (document: Document): boolean =>
  getUncertaintyPrompts(document).some((prompt) => prompt.required !== false);

export const getExtractedVerificationFields = (document: Document): ExtractedVerificationFields => {
  const prompts = getUncertaintyPrompts(document);
  const byId = Object.fromEntries(prompts.map((p) => [p.id, p]));
  const suggestedCategory = byId.clarify_bill_category?.context?.currentCategory;
  const detectedFuel = byId.clarify_fuel_type?.context?.detected;

  const rawVendor = document.extractedData?.vendor?.name?.trim() || '';
  const vendorName = sanitizeDisplayVendor(rawVendor, '');

  return {
    vendorName,
    date: formatDateForInput(document.extractedData?.date),
    gstin: readGstin(document),
    invoiceNumber: readInvoiceNumber(document),
    amount: Number(document.extractedData?.amount) > 0 ? String(document.extractedData?.amount) : '',
    category: suggestedCategory != null && String(suggestedCategory).trim()
      ? String(suggestedCategory)
      : (document.extractedData?.category || ''),
    fuelType: detectedFuel != null ? String(detectedFuel) : '',
    electricityUnitPriceInr: '',
    waterUnitPriceInr: '',
    wasteUnitCostInr: '',
    fuelUnitPriceInr: '',
    activityQuantity: '',
    activityUnit: 'kwh',
    reviewConfirmed: false,
  };
};

/**
 * Build API payload: core verify fields + uncertainty answers for outstanding prompts.
 */
export const buildVerifyExtractedDataPayload = (
  form: ExtractedVerificationFields,
  prompts: UncertaintyPrompt[] = []
): Record<string, unknown> => {
  const payload: Record<string, unknown> = {
    vendorName: form.vendorName,
    date: form.date,
    gstin: form.gstin,
    invoiceNumber: form.invoiceNumber,
  };
  const amount = Number(String(form.amount ?? '').replace(/,/g, ''));
  if (Number.isFinite(amount) && amount > 0) {
    payload.amount = amount;
  }

  const ids = new Set(prompts.map((p) => p.id));

  if (ids.has('clarify_bill_category') && form.category) {
    payload.category = form.category;
  }
  if (ids.has('clarify_fuel_type') && form.fuelType) {
    payload.fuelType = form.fuelType;
  }
  if (ids.has('clarify_electricity_unit_price') && form.electricityUnitPriceInr) {
    const n = Number(form.electricityUnitPriceInr);
    if (Number.isFinite(n) && n > 0) payload.electricityUnitPriceInr = n;
  }
  if (ids.has('clarify_water_unit_price') && form.waterUnitPriceInr) {
    const n = Number(form.waterUnitPriceInr);
    if (Number.isFinite(n) && n > 0) payload.waterUnitPriceInr = n;
  }
  if (ids.has('clarify_waste_unit_cost') && form.wasteUnitCostInr) {
    const n = Number(form.wasteUnitCostInr);
    if (Number.isFinite(n) && n > 0) payload.wasteUnitCostInr = n;
  }
  if (ids.has('clarify_fuel_unit_price') && form.fuelUnitPriceInr) {
    const n = Number(form.fuelUnitPriceInr);
    if (Number.isFinite(n) && n > 0) payload.fuelUnitPriceInr = n;
  }
  if (ids.has('clarify_electricity_kwh') && form.activityQuantity) {
    const n = Number(form.activityQuantity);
    if (Number.isFinite(n) && n > 0) {
      payload.activityQuantity = n;
      payload.activityUnit = form.activityUnit || 'kwh';
    }
  }
  if (ids.has('clarify_review_confirmation') && form.reviewConfirmed) {
    payload.reviewConfirmed = true;
  }

  return payload;
};

export const getExtractedDataVerificationState = (
  document: Document
): ExtractedDataVerificationState => ({
  status: document.extractedDataVerification?.status === 'verified' ? 'verified' : 'pending',
  acceptedForEmissions: Boolean(document.extractedDataVerification?.acceptedForEmissions),
  verifiedAt: document.extractedDataVerification?.verifiedAt || null,
  correctionCount: document.extractedDataVerification?.correctionCount || 0,
});


/**
 * DEEP-BUG-025: Processed must mean usable extraction.
 * True when vendor, amount, and invoice essentials are all missing.
 */
export const documentLacksExtractionEssentials = (document: Document): boolean => {
  const data = document.extractedData;
  if (!data) {
    return true;
  }
  const vendor =
    (typeof data.vendor === 'string' ? data.vendor : data.vendor?.name)?.trim() || '';
  const invoice = readInvoiceNumber(document);
  const amount = Number(data.amount);
  const hasAmount = Number.isFinite(amount) && amount > 0;
  const hasLineItems = Array.isArray(data.items)
    && data.items.some((item) => resolveItemAmount(item) > 0);
  return !vendor && !invoice && !hasAmount && !hasLineItems;
};

/** Display status for list/detail badges when extraction is empty. */
export const resolveDocumentDisplayStatus = (
  document: Document
): { status: string; label: string; emptyExtraction: boolean } => {
  const emptyExtraction =
    document.status === 'processed' && documentLacksExtractionEssentials(document);
  if (emptyExtraction) {
    return {
      status: 'failed',
      label: 'Empty extraction',
      emptyExtraction: true,
    };
  }
  return {
    status: document.status,
    label: document.status
      ? document.status.charAt(0).toUpperCase() + document.status.slice(1)
      : '',
    emptyExtraction: false,
  };
};


export const shouldShowExtractedDataVerification = (document: Document): boolean =>
  document.status === 'processed'
  && Boolean(document.extractedData)
  && !document.duplicateDetection?.isDuplicate;

export const isExtractedDataVerified = (
  document: Pick<Document, 'extractedDataVerification'>
): boolean =>
  document.extractedDataVerification?.status === 'verified'
  && Boolean(document.extractedDataVerification?.acceptedForEmissions);
