const MIN_REASONABLE_YEAR = 1990;
/** Reject far-future OCR garbage (QA saw 2050). Allow a small forward buffer. */
const MAX_REASONABLE_YEAR = new Date().getUTCFullYear() + 1;
const EXCEL_EPOCH_UTC = Date.UTC(1899, 11, 30);

function dateFromExcelSerial(serial: number): Date | null {
  if (!Number.isFinite(serial) || serial < 20000 || serial > 80000) return null;
  const parsed = new Date(EXCEL_EPOCH_UTC + Math.floor(serial) * 86400000);
  if (Number.isNaN(parsed.getTime())) return null;
  const year = parsed.getUTCFullYear();
  if (year < MIN_REASONABLE_YEAR || year > MAX_REASONABLE_YEAR) return null;
  return parsed;
}

/**
 * Excel serials stored as a calendar year (+046256-01-01) become the real day.
 * Years outside 1990..next year (including 2050) stay rejected.
 */
export function coerceTransactionDate(
  value: string | number | Date | null | undefined
): Date | null {
  if (value == null || value === '') return null;
  if (typeof value === 'number') return dateFromExcelSerial(value);

  const raw = value instanceof Date ? '' : String(value).trim();
  if (raw && /^\d{4,6}(\.\d+)?$/.test(raw)) return dateFromExcelSerial(Number(raw));

  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) return null;
  const year = parsed.getUTCFullYear();
  if (year >= 20000 && year <= 80000) return dateFromExcelSerial(year);
  if (year < MIN_REASONABLE_YEAR || year > MAX_REASONABLE_YEAR) return null;
  return parsed;
}

/**
 * Format dates for operational ledgers. Recovers Excel-serial years (46256)
 * and rejects far-future OCR noise (2050) so the UI stays auditable.
 */
export function sanitizeDisplayDate(
  value: string | number | Date | null | undefined,
  fallback = 'Date unavailable'
): string {
  const parsed = coerceTransactionDate(value);
  if (!parsed) return fallback;

  return new Intl.DateTimeFormat('en-IN', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    timeZone: 'UTC',
  }).format(parsed);
}

export function isReasonableTransactionDate(value: string | number | Date | null | undefined): boolean {
  return coerceTransactionDate(value) != null;
}
